from pathlib import Path
import json,csv,io,gzip,hashlib,copy
B=Path(__file__).resolve().parent;ROOT=B.parent.parent
base=json.loads((ROOT/'site/data/portraits.json').read_text());records=[];results=[]
for portrait,stem,geo,scale,period in [('carmel','acs5-rentburden2024','1600000US0611250','city','2020–2024 ACS five-year'),('monterey-county','acs1-rentburden2024','0500000US06053','county','2024 ACS one-year')]:
 meta=json.loads((B/'activity'/f'{stem}.json').read_text());path=B/meta.get('stored_path',meta['raw_path']);raw=path.read_bytes();raw=gzip.decompress(raw) if path.suffix=='.gz' else raw;assert hashlib.sha256(raw).hexdigest()==meta['sha256']
 row=next(r for r in csv.DictReader(io.StringIO(raw.decode()),delimiter='|') if r['GEO_ID']==geo)
 numerator=sum(int(row[f'B25070_E{c:03}']) for c in [7,8,9,10]);denominator=int(row['B25070_E001'])-int(row['B25070_E011']);pct=numerator/denominator*100;strict_min=(numerator-int(row['B25070_E007']))/denominator*100
 result={'portrait':portrait,'row':row,'numerator_at_least30':numerator,'denominator_computable':denominator,'percent_at_least30':pct,'strict_over30_lower_bound':strict_min,'strict_over30_upper_bound':pct,'period':period};results.append(result)
 before=next(d for d in next(p for p in base['portraits'] if p['slug']==portrait)['dimensions'] if d['slug']=='housing')['indicators'][0]
 after=copy.deepcopy(before);after.update(name='Renter-occupied units paying 30% or more of income in gross rent',value=round(pct,1),year=2024,unit='% of renter-occupied units with computable rent burden',target=None,scoring=None,level_pct=None,status='source-supported-observation',source='U.S. Census Bureau ACS 2024 detailed table B25070 (official table-based summary file)',source_url=meta['url'],source_tier=2,geography=scale,geographic_scale=scale,evidence_path='evidence/carmel-monterey-rentburden-extract.png',pdf_path=None,evidence={'snapshot_path':'evidence/carmel-monterey-rentburden-extract.png','captured_at':meta['captured_at']},notes=f'{period}; exact geography {geo}. B25070 estimates: four bins from 30.0% upward sum to {numerator}; total renter-occupied units minus not-computed units = {denominator}. {numerator}/{denominator} × 100 = {pct:.8f}%. This establishes a related AT-LEAST-30% observation, not the configured strict OVER-30% point estimate. Published bins only bound the strict share between {strict_min:.8f}% and {pct:.8f}%; a safe exact point cannot be recovered. Target and score remain null; no definition or threshold is silently changed. Constituent 90% MOEs are retained in the raw source row; no combined-ratio MOE was calculated. The official primary table now replaces the earlier Census Reporter/API-access fallback.')
 support={'url':meta['url'],'raw_path':meta.get('stored_path',meta['raw_path']),'raw_sha256':meta['sha256'],'raw_encoding':meta.get('storage_encoding','identity'),'captured_at':meta['captured_at'],'snapshot_path':after['evidence_path'],'period':period,'scale':scale}
 if meta.get('stored_sha256'):support['stored_sha256']=meta['stored_sha256']
 record={'id':portrait+':housing:0:primary-supplement','portrait':portrait,'dimension':'housing','indicator_index':0,'kind':'replace','before':before,'after':after,'field_diff':{k:{'before':before.get(k),'after':v} for k,v in after.items() if before.get(k)!=v},'reason':'Restore direct primary-source support while keeping the strict-threshold point estimate unresolved and unscored.','source_support':[support],'review_required':True};records.append(record)
(B/'calculations/rentburden-results.json').write_text(json.dumps(results,indent=2)+'\n')
body='<!doctype html><meta charset="utf-8"><title>Carmel and Monterey rent burden</title><style>body{font:20px/1.45 system-ui;max-width:1100px;margin:44px auto}table{border-collapse:collapse;width:100%;font-size:17px}td,th{border:1px solid #abc;padding:10px}pre{font-size:16px;white-space:pre-wrap}</style><h1>Rent burden — official ACS primary tables</h1><p>Researcher-generated faithful extract from archived Census B25070 summary files. This is the share paying AT LEAST 30% of income in gross rent among units with a computable ratio. It is not the strict over-30% measure.</p><table><tr><th>Place / period</th><th>Numerator ≥30%</th><th>Computable denominator</th><th>Observed ≥30%</th><th>Bounds for strict &gt;30%</th></tr>'
for r in results:body+=f"<tr><td>{r['portrait']} / {r['period']}</td><td>{r['numerator_at_least30']}</td><td>{r['denominator_computable']}</td><td>{r['percent_at_least30']:.8f}%</td><td>{r['strict_over30_lower_bound']:.8f}%–{r['strict_over30_upper_bound']:.8f}%</td></tr>"
body+='</table><p>The 30.0–34.9% bin contains exactly-30% units. They cannot be separated from the published bins. No exact strict-over-30% share or corresponding score is asserted. Denominator excludes B25070_E011 (not computed). All raw estimates and 90% MOEs are retained; no combined-ratio MOE was calculated.</p>'
for r in results:body+='<h2>'+r['portrait']+'</h2><pre>'+json.dumps(r['row'],indent=2)+'</pre>'
(B/'calculations/rentburden-extract.html').write_text(body)
(B/'findings/supplemental-housing.json').write_text(json.dumps({'schema_version':1,'baseline_snapshot_sha256':hashlib.sha256((ROOT/'site/data/portraits.json').read_bytes()).hexdigest(),'research_model':'gpt-6.1-sol','reasoning_effort':'high','amendments':records},indent=2,ensure_ascii=False)+'\n')
print([(r['portrait'],r['percent_at_least30'],r['strict_over30_lower_bound']) for r in results])
